function Box(val) {
  this.val = val;
  this.read = () => this.val;
}
const base = { val: 0 };
const Make = Box.bind(base);
const b = new Make(42);
const other = { val: 99, read: b.read };
console.log(b.val);
console.log(base.val);
console.log(other.read());
console.log(b.read.call(other));
